"""Export only aggregate research metrics and a readable verification report."""
import argparse,json
from pathlib import Path
import numpy as np
KEYS=['accuracy','macro_precision','macro_recall','macro_f1','weighted_f1','false_negatives','false_positives','false_negative_rate','false_positive_rate','binary_roc_auc','binary_average_precision']

def summarize(report):
 results={}
 for protocol in report['protocols']:
  methods=sorted(set(r['method'] for r in report['runs'] if r['protocol']==protocol));rows=[]
  for method in methods:
   runs=[r for r in report['runs'] if r['protocol']==protocol and r['method']==method];stats={}
   for key in KEYS:
    vals=[r['test'][key] for r in runs if r['test'][key] is not None];stats[key]={'mean':float(np.mean(vals)),'std':float(np.std(vals,ddof=1)) if len(vals)>1 else 0.,'min':float(min(vals)),'max':float(max(vals))} if vals else None
   rows.append({'method':method,'seeds':[r['seed'] for r in runs],'validation_macro_f1_mean':float(np.mean([r['validation']['macro_f1'] for r in runs])),'test':stats,'mean_inference_ms_per_1000':float(np.mean([r['inference_ms_per_1000'] for r in runs])),'per_seed':[{'seed':r['seed'],'validation':r['validation'],'test':r['test'],'selected_round':r.get('selected_round'),'test_by_site':r['test_by_site']} for r in runs]})
  results[protocol]={'partitions':report['protocols'][protocol],'selected_method':report['selections'][protocol]['selected_method'],'models':rows}
 curves={}
 for key,run in report['federated_runs'].items():
  if run['strategy']=='local_only':continue
  curves[key]={'strategy':run['strategy'],'rounds':run['rounds'],'mu':run['mu'],'clients':[{'site':c['site'],'examples':c['examples']} for c in run['clients']],'selected_round':run['selected_round'],'history':[{'round':r['round'],'validation_macro_f1':r['validation_macro_f1'],'mean_local_loss':float(np.mean([c['local_loss'] for c in r['clients']])),'examples':r['aggregation_examples'],'transmitted_parameter_bytes':sum(c['parameter_bytes'] for c in r['clients']),'optimizer_steps':sum(c['optimizer_steps'] for c in r['clients'])} for r in run['history']]}
 return {'status':report['status'],'study':report['study'],'dataset_sha256':report['dataset_sha256'],'source_sha256':report['source_sha256'],'configuration':report['configuration'],'versions':report['versions'],'audit':report['audit'],'results':results,'federated_runs':curves,'limitations':report['limitations'],'interpretation':'Mean and sample standard deviation across three initialization seeds, not confidence intervals or independent data replications. New purged protocols are not directly comparable with the original dashboard baseline.'}

def main():
 a=argparse.ArgumentParser();a.add_argument('--experiment',type=Path,default=Path('artifacts/research-v2-final'));a.add_argument('--public',type=Path,default=Path('public/research.json'));args=a.parse_args();report=json.loads((args.experiment/'report.json').read_text(encoding='utf-8'));s=summarize(report);args.public.parent.mkdir(parents=True,exist_ok=True);args.public.write_text(json.dumps(s,indent=2,allow_nan=False),encoding='utf-8')
 lines=['# Aesculyn v2 — Data validation, model comparison, and federated experiments','','## Status','Completed offline experiments. This is a process-isolated local federation, not a hospital deployment.','', '## Dataset audit']
 for k in ['rows','columns','missing_cells','duplicate_collection_keys','repeated_feature_vectors','conflicting_feature_vectors','rows_with_conflicting_features','malicious_windows','malicious_annotation_exact_matches','malicious_annotation_matches_with_2s_tolerance','benign_windows_inside_attack_intervals','unique_run_ids']:lines.append(f"- {k}: {s['audit'][k]}")
 lines+=['','Conflicting feature-label groups are reported but are NOT used to filter training using evaluation labels. Repeated feature vectors are removed globally using target-independent partition and original-index precedence; contradictions remain a data-quality limitation. Timestamp boundaries are purged by 60 seconds and made globally chronological across sites. Annotation tolerance is diagnostic, not independently established capture-window semantics.','','## Frozen experimental configuration', 'Three seeds: 17, 29, 43. Four centralized candidates: Gaussian naive Bayes, weighted multinomial logistic regression, a histogram-binned random forest, and a 25→64→32→8 ReLU MLP. All are NumPy reference implementations. MLP SGD learning rate .03, momentum .9, inverse-square-root training class weights, 20 rounds/blocks × 2 local epochs. FedAvg mu=0, FedProx mu=.01. Same architecture and initialization per seed. Checkpoints selected by validation macro-F1. Model family chosen by mean validation macro-F1 before test prediction.','', 'Independent local-only site models are also trained. Centralized MLP optimizer steps and round/reset schedule match the stated training budget; local-only and federated models each see only local client training batches. Centralized pooled training naturally performs more minibatch updates per block than an individual client.','','## Results']
 for protocol,result in s['results'].items():
  p=result['partitions'];lines+=['',f'### {protocol}',f"Train/validation/test: {p['counts']['train']:,} / {p['counts']['val']:,} / {p['counts']['test']:,}. Training sites: {', '.join(p['training_sites'])}; test sites: {', '.join(p['test_sites'])}.",f"Validation-selected method: **{result['selected_method']}**.",'','| Method | Val macro F1 | Test accuracy | Test macro F1 (mean ± SD) | FN mean | FP mean | FPR |','|---|---:|---:|---:|---:|---:|---:|']
  for r in sorted(result['models'],key=lambda r:-r['validation_macro_f1_mean']):
   t=r['test'];lines.append(f"| {r['method']} | {100*r['validation_macro_f1_mean']:.2f}% | {100*t['accuracy']['mean']:.2f}% | {100*t['macro_f1']['mean']:.2f}% ± {100*t['macro_f1']['std']:.2f} | {t['false_negatives']['mean']:.1f} | {t['false_positives']['mean']:.1f} | {100*t['false_positive_rate']['mean']:.2f}% |")
 lines+=['','Standard deviation across seeds is not an uncertainty interval for unseen hospitals. The new test subsets differ from the original baseline evaluation; apparent improvements must not be treated as a same-test comparison. Compare methods only within the same v2 protocol.','','## Federation implementation','One spawned process per site loads its own private partition. Each round sends global weights to clients, executes actual local SGD, and returns weights, sample counts, loss, and timing. FedAvg uses sample-count-weighted averaging. FedProx adds mu/2 times the squared distance to the received global parameters. Selected global checkpoints and all round logs are saved. Client training data never cross the coordinator pipe during rounds.','', 'The coordinator prepares partitions locally and can access all files. Training normalization moments and label counts are aggregated without secure aggregation. Thus this is a genuine algorithmic federated experiment but not a privacy-secure distributed hospital system. Flower and PyTorch were not used in this execution.','','## Environment constraints','An isolated PyTorch/scikit-learn installation hit low disk space; after a smaller installation, Windows Application Control blocked a native scikit-learn module. Security controls were preserved. NumPy reference implementations with analytic-gradient, split, probability, and aggregation tests were used instead. The partial dependency environment is not required to reproduce this study; only NumPy, pandas, and threadpoolctl are needed.','','## Reproduction','```sh','python -m pip install -r requirements.txt','python -m research.run --archive "/path/to/dataset.zip" --output artifacts/research-v2-final','python research_report.py --experiment artifacts/research-v2-final --public public/research.json','python -m unittest test_research -v','python research_predict.py --experiment artifacts/research-v2-final --input batch.csv --output predictions.csv','```','','The output directory must be new/empty. configuration.json is written before training; selection_lock.json before test prediction. Source, dataset, partition, and model digests are recorded. Private partitions, checkpoints and predictions remain under ignored artifacts/. No archive-extracted code is executed.','','## Limitations',*['- '+v for v in s['limitations']]]
 Path('RESEARCH_RESULTS.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print('Aggregate export and report written.')
if __name__=='__main__':main()
